  <?php if($person):$defaults=['basic_salary'=>0,'dearness_allowance'=>0,'hra'=>0,'other_allowances'=>0,'epf_covered'=>1,'epf_rate'=>12,'pt_exempt'=>0];$s=array_merge($defaults,$person);foreach($defaults as $k=>$v)if($s[$k]===null)$s[$k]=$v;$latestQ=$pdo->prepare('SELECT id FROM payslips WHERE employee_id=? ORDER BY period DESC LIMIT 1');$latestQ->execute([$chosen]);$latestId=(int)$latestQ->fetchColumn();?><div class="payroll-person"><div><span class="eyebrow"><?=e($person['employee_id'])?> · <?=e($person['department_name']??'Unassigned')?></span><h3><?=e($person['first_name'].' '.$person['last_name'])?></h3><p><?=e($person['designation'])?> · Joined <?=e(date('M j, Y',strtotime($person['joining_date'])))?></p></div><?php if($latestId):?><a class="button secondary" href="<?=e($base.'/payroll-payslip.php?id='.$latestId)?>">Open latest payslip</a><?php endif;?></div>
