  <?php if($person):?><script>
  (()=>{const root=document.querySelector('.payroll-preview'),form=document.querySelector('.payroll-form'),issue=document.querySelector('form input[name="action"][value="payslip_issue"]')?.form;if(!root||!form)return;const holidays=new Set(JSON.parse(root.dataset.holidays||'[]')),joining=root.dataset.joiningDate;const value=(f,n)=>Number.parseFloat(f.elements[n]?.value||'0')||0;const money=n=>'₹'+Number(n||0).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});function workdays(start,end){let count=0;for(let d=new Date(start+'T12:00:00');d<=new Date(end+'T12:00:00');d.setDate(d.getDate()+1)){const iso=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');if(d.getDay()!==0&&!holidays.has(iso))count++;}return count;}function setPayday(){if(!issue)return;const [y,m]=issue.elements.period.value.split('-');issue.elements.pay_date.value=new Date(Number(y),Number(m),7).getFullYear()+'-'+String(new Date(Number(y),Number(m),7).getMonth()+1).padStart(2,'0')+'-07';}function update(){const basic=value(form,'basic_salary'),da=value(form,'da'),hra=value(form,'hra'),allow=value(form,'other_allowances'),extra=issue?value(issue,'other_earnings'):0,manual=issue?value(issue,'other_deductions'):0,period=issue?.elements.period.value||new Date().toISOString().slice(0,7),[year,month]=period.split('-'),start=period+'-01',last=new Date(Number(year),Number(month),0),end=last.getFullYear()+'-'+String(last.getMonth()+1).padStart(2,'0')+'-'+String(last.getDate()).padStart(2,'0'),scheduled=workdays(start,end),from=joining>start?joining:start,payable=joining>end?0:workdays(from,end),factor=scheduled?payable/scheduled:0,rate=value(form,'epf_rate')||12,covered=!!form.elements.epf_covered?.checked,exempt=!!form.elements.pt_exempt?.checked,prBasic=basic*factor,prDa=da*factor,prHra=hra*factor,prAllow=allow*factor,gross=prBasic+prDa+prHra+prAllow+extra;let employer=0,wage=0;if(covered){for(let i=0;i<16;i++){wage=Math.min(25000,prBasic+prDa+Math.max(0,prHra+prAllow+extra-(gross+employer)/2));const next=Math.round(wage*rate/100);if(next===employer)break;employer=next;}}const pf=Math.round(wage*rate/100),pt=exempt||gross<=12000?0:200;root.querySelector('[data-payroll-gross]').textContent=money(gross);root.querySelector('[data-payroll-days]').textContent=payable+' / '+scheduled;root.querySelector('[data-payroll-wage]').textContent=money(wage);root.querySelector('[data-payroll-pf]').textContent=money(pf);root.querySelector('[data-payroll-pt]').textContent=money(pt);root.querySelector('[data-payroll-other-deduction]').textContent=money(manual);root.querySelector('[data-payroll-net]').textContent=money(Math.max(0,gross-pf-pt-manual));}issue?.elements.period.addEventListener('change',()=>{setPayday();update();});document.querySelectorAll('.payroll-form input,.payroll-form select,form input[name="period"],form input[name="other_earnings"],form input[name="other_deductions"]').forEach(el=>el.addEventListener('input',update));update();})();
  </script><?php endif;?>
  <?php $st=$pdo->query('SELECT p.*,e.employee_id,e.first_name,e.last_name FROM payslips p JOIN employees e ON e.id=p.employee_id ORDER BY p.period DESC,e.first_name,e.last_name');$slips=$st->fetchAll();?><section class="panel payroll-panel"><div class="panel-head"><div><h2>Issued payslips</h2><p><?=count($slips)?> records · only issued statements appear in employee accounts.</p></div></div><?php if(!$slips):empty_state('calendar','No payslips issued','Configure a salary structure, then issue the first monthly payslip.');else:?><div class="table-wrap"><table><thead><tr><th>EMPLOYEE</th><th>MONTH</th><th>GROSS</th><th>NET PAY</th><th>PAY DATE</th><th></th></tr></thead><tbody><?php foreach($slips as $p):?><tr><td><b><?=e($p['first_name'].' '.$p['last_name'])?></b><small class="table-sub"><?=e($p['employee_id'])?></small></td><td><?=e(date('F Y',strtotime($p['period'].'-01')))?></td><td>₹<?=number_format((float)$p['gross_salary'],2)?></td><td><b>₹<?=number_format((float)$p['net_salary'],2)?></b></td><td><?=e(date('M j, Y',strtotime($p['pay_date'])))?></td><td><a class="button secondary small-button" href="<?=e($base.'/payroll-payslip.php?id='.(int)$p['id'])?>">View / save PDF</a></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
