  $st=$pdo->prepare('SELECT * FROM payslips WHERE employee_id=? ORDER BY period DESC');$st->execute([$eid]);$slips=$st->fetchAll();?><section class="panel payroll-panel"><div class="panel-head"><div><h2>Your monthly pay</h2><p>Only payslips issued by the administrator are shown here.</p></div></div><?php if(!$slips):empty_state('rupee','No payslips available yet','Your payslip will appear here once payroll has been issued.');else:?><div class="table-wrap"><table><thead><tr><th>MONTH</th><th>GROSS PAY</th><th>DEDUCTIONS</th><th>NET PAY</th><th>PAY DATE</th><th></th></tr></thead><tbody><?php foreach($slips as $p):?><tr><td><b><?=e(date('F Y',strtotime($p['period'].'-01')))?></b></td><td>₹<?=number_format((float)$p['gross_salary'],2)?></td><td>₹<?=number_format((float)$p['total_deductions'],2)?></td><td><strong>₹<?=number_format((float)$p['net_salary'],2)?></strong></td><td><?=e(date('M j, Y',strtotime($p['pay_date'])))?></td><td><a class="button secondary small-button" href="<?=e($base.'/payroll-payslip.php?id='.(int)$p['id'])?>">View / save PDF</a></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><?php
